import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);
    const [viewRoom, setViewRoom] = useState(null);
    const [loading, setLoading] = useState(false);
    const [invoiceData, setInvoiceData] = useState(null);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // XÁC ĐỊNH TRẠNG THÁI THỜI GIAN
    const isPastMonth = selectedYear < currentYear || (selectedYear === currentYear && selectedMonth < currentMonth);
    const isCurrentMonth = selectedYear === currentYear && selectedMonth === currentMonth;
    const isFutureMonth = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth > currentMonth);

    useEffect(() => {
        setLoading(true);
        setTimeout(() => {
            if (isPastMonth) {
                setInvoiceData({
                    content: `Tiền phòng tháng ${selectedMonth}/${selectedYear}`,
                    amount: "5.000.000đ",
                    time: `01/${selectedMonth.toString().padStart(2, '0')}/${selectedYear}`,
                    status: "ĐÃ THANH TOÁN"
                });
            } else {
                setInvoiceData(null);
            }
            setLoading(false);
        }, 200);
    }, [selectedMonth, selectedYear, isPastMonth]);

    // HÀM XÁC ĐỊNH MÀU SẮC PHÒNG (Tối ưu để sau này nhận status từ Backend)
    const getRoomStyle = (room) => {
        const isSelected = viewRoom === room;

        // 1. Nếu là tháng đã qua: Mặc định xanh (Đã thu)
        if (isPastMonth) return {
            bg: isSelected ? '#8b5e5e' : '#e6f4ea',
            color: isSelected ? '#fff' : '#1e7e34',
            border: '1px solid #c3e6cb'
        };

        // 2. Nếu là tháng hiện tại: Mặc định vàng (Chưa thu)
        if (isCurrentMonth) return {
            bg: isSelected ? '#8b5e5e' : '#ffcc00',
            color: isSelected ? '#fff' : '#333',
            border: '1px solid #e6b800'
        };

        // 3. Nếu là tháng tương lai: Mờ và Trắng
        return {
            bg: isSelected ? '#8b5e5e' : 'rgba(255,255,255,0.5)',
            color: isSelected ? '#fff' : '#999',
            border: '1px solid rgba(0,0,0,0.05)'
        };
    };

    const totalReceived = isPastMonth ? (5000000 * 45) : 0;

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: '100%'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedMonth} onChange={(e) => {setSelectedMonth(parseInt(e.target.value)); setViewRoom(null);}} 
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select value={selectedYear} onChange={(e) => {setSelectedYear(parseInt(e.target.value)); setViewRoom(null);}} 
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG */}
                <div className="custom-scrollbar" style={{ 
                    width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '12px', backgroundColor: 'rgba(0,0,0,0.2)', borderRadius: '20px'
                }}>
                    {allRooms.map(room => {
                        const style = getRoomStyle(room);
                        return (
                            <div 
                                key={room} 
                                onClick={() => setViewRoom(room)}
                                style={{ 
                                    background: style.bg, 
                                    color: style.color, 
                                    border: style.border,
                                    padding: '10px 0', borderRadius: '8px', 
                                    textAlign: 'center', fontSize: '11px', fontWeight: 'bold', 
                                    cursor: 'pointer', transition: '0.2s',
                                    opacity: isFutureMonth && viewRoom !== room ? 0.5 : 1
                                }}>
                                {room}
                            </div>
                        );
                    })}
                </div>

                {/* CỘT PHẢI: CHI TIẾT */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '25px', 
                    padding: '30px', display: 'flex', flexDirection: 'column',
                    color: '#000', boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)', overflow: 'hidden'
                }}>
                    <div style={{ 
                        marginBottom: '20px', padding: '20px', backgroundColor: '#f8f9fa', 
                        borderRadius: '15px', borderLeft: '10px solid #8b5e5e', flexShrink: 0 
                    }}>
                        <div style={{ fontSize: '16px', fontWeight: 'bold', color: '#777' }}>Doanh thu thực tế (T{selectedMonth}/{selectedYear}):</div>
                        <div style={{ fontSize: '40px', fontWeight: '900', color: totalReceived > 0 ? '#28a745' : '#999' }}>
                            {totalReceived.toLocaleString()}đ
                        </div>
                    </div>

                    <h3 style={{ borderBottom: '2px solid #eee', paddingBottom: '15px', marginBottom: '15px' }}>
                        {viewRoom ? `Hóa đơn phòng: ${viewRoom}` : 'Chọn phòng để kiểm tra'}
                    </h3>

                    <div style={{ flex: 1, overflowY: 'auto' }}>
                        {loading ? (
                            <div style={{ textAlign: 'center', padding: '50px' }}>Đang truy xuất...</div>
                        ) : viewRoom ? (
                            invoiceData ? (
                                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                    <thead>
                                        <tr style={{ textAlign: 'left', color: '#888', fontSize: '14px', borderBottom: '2px solid #f1f1f1' }}>
                                            <th style={{ padding: '12px' }}>Nội dung</th>
                                            <th style={{ padding: '12px' }}>Số tiền</th>
                                            <th style={{ padding: '12px' }}>Trạng thái</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr>
                                            <td style={{ padding: '15px 12px', fontWeight: '500' }}>{invoiceData.content}</td>
                                            <td style={{ padding: '15px 12px', color: '#28a745', fontWeight: '700' }}>{invoiceData.amount}</td>
                                            <td style={{ padding: '15px 12px' }}>
                                                <span style={{ padding: '5px 10px', backgroundColor: '#e6f4ea', color: '#1e7e34', borderRadius: '6px', fontSize: '11px', fontWeight: 'bold' }}>{invoiceData.status}</span>
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            ) : (
                                <div style={{ textAlign: 'center', padding: '60px 0' }}>
                                    <div style={{ fontSize: '50px', marginBottom: '10px' }}>⚠️</div>
                                    <div style={{ fontSize: '18px', fontWeight: 'bold', color: '#ffcc00' }}>CHƯA THANH TOÁN</div>
                                    <p style={{ color: '#999', marginTop: '10px' }}>Kỳ hóa đơn này đang chờ cư dân thực hiện giao dịch.</p>
                                </div>
                            )
                        ) : (
                            <div style={{ textAlign: 'center', padding: '80px 0', color: '#ccc', fontStyle: 'italic' }}>Chọn phòng để xem chi tiết...</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
